solution:
def can_attend_all(meetings: list[list[int]]) -> bool:
    meetings = sorted(meetings)
    for prev, cur in zip(meetings, meetings[1:]):
        if cur[0] < prev[1]:                 # starts before the previous one ends
            return False
    return True

perf.naive:
def can_attend_all(meetings: list[list[int]]) -> bool:
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):     # every pair
            a, b = meetings[i], meetings[j]
            if a[0] < b[1] and b[0] < a[1]:
                return False
    return True
